&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Manieur de hache&lt;div style=&quot;float:right;&quot;&gt;FP 2&lt;/div&gt;&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : &lt;a class=&quot;pagelink&quot; href=&quot;Manuel-Des-Pnj-(Contenu).html&quot; title=&quot;Manuel des PNJ (Contenu)&quot;&gt;Manuel des PNJ p. 11&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 600
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; 3
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Humain.html&quot; title=&quot;Humain (sous-type)&quot;&gt;humain&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Orque.html&quot; title=&quot;Orque (sous-type)&quot;&gt;orque&lt;/a&gt;) de taille M, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +1 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +6
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 15, contact 9, pris au d&#233;pourvu 14 (armure +6, Dex +1, rage -2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 40 (3d12+15)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +2, &lt;b&gt;Vig&lt;/b&gt; +7, &lt;b&gt;Vol&lt;/b&gt; +3
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#ESQUIVEINSTINCTIVE&quot; title=&quot;Le barbare&quot;&gt;esquive instinctive&lt;/a&gt;, f&#233;rocit&#233; orque, &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#SENSDESPIEGES&quot; title=&quot;Le barbare&quot;&gt;sens des pi&#232;ges +1&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; grande hache de ma&#238;tre, +9 (1d12+7/&#215;3)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; fronde de ma&#238;tre, +5 (1d4+5)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt; (10 rounds/jour), &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#POUVOIRSDERAGE&quot; title=&quot;Le barbare&quot;&gt;pouvoirs de rage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage.html#REGARDINTIMIDANT&quot; title=&quot;Les pouvoirs de rage du barbare&quot;&gt;regard intimidant&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pendant le combat.&lt;/b&gt; Le barbare utilise son regard intimidant &#224; chaque round. Il commence par attaquer avant de braquer son regard sur le bless&#233;.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Statistiques de base.&lt;/b&gt; Voici les statistiques du barbare quand il n’est pas enrag&#233; : &lt;b&gt;CA&lt;/b&gt; 17, contact 11, pris au d&#233;pourvu 16 ; &lt;b&gt;pv&lt;/b&gt; 34 ; &lt;b&gt;Vig&lt;/b&gt; +5, &lt;b&gt;Vol&lt;/b&gt; +1 ; &lt;b&gt;Corps &#224; corps&lt;/b&gt; grande hache de ma&#238;tre, +7 (1d12+4/x3) ; &lt;b&gt;&#192; distance&lt;/b&gt; fronde de ma&#238;tre, +5 (1d4+3) ; &lt;b&gt;For&lt;/b&gt; 17, &lt;b&gt;Con&lt;/b&gt; 14 ; &lt;b&gt;BMO&lt;/b&gt; +6 ; &lt;b&gt;Comp&#233;tences&lt;/b&gt; Escalade +5, Intimidation +12, Natation +3.
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Statistiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 21, &lt;b&gt;Dex&lt;/b&gt; 13, &lt;b&gt;Con&lt;/b&gt; 18, &lt;b&gt;Int&lt;/b&gt; 8, &lt;b&gt;Sag&lt;/b&gt; 10, &lt;b&gt;Cha&lt;/b&gt; 12
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +3 ; &lt;b&gt;BMO&lt;/b&gt; +8 ; &lt;b&gt;DMD&lt;/b&gt; 17
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Force-Intimidante.html&quot; title=&quot;Force intimidante&quot;&gt;Force intimidante&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +7, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +14, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +5, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +6, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +4
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun, orque
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; armes famili&#232;res, &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#DEPLACEMENTACCELERE&quot; title=&quot;Le barbare&quot;&gt;d&#233;placement acc&#233;l&#233;r&#233;&lt;/a&gt;, sang orque
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Potions-Magiques.html&quot; title=&quot;Les potions magiques&quot;&gt;potion&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Bien.html&quot; title=&quot;Protection contre le Bien&quot;&gt;protection contre le Bien&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Potions-Magiques.html&quot; title=&quot;Les potions magiques&quot;&gt;potion&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Restauration-Partielle.html&quot; title=&quot;Restauration partielle&quot;&gt;restauration partielle&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Potions-Magiques.html&quot; title=&quot;Les potions magiques&quot;&gt;potion&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cotte-De-Mailles-(Armure).html&quot; title=&quot;Cotte de mailles&quot;&gt;cotte de mailles&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Fronde-(Arme).html&quot; title=&quot;Fronde&quot;&gt;fronde&lt;/a&gt; avec 10 &lt;a class=&quot;pagelink&quot; href=&quot;Billes-De-Fronde-(Arme).html&quot; title=&quot;Billes de fronde (10)&quot;&gt;billes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Grande-Hache-(Arme).html&quot; title=&quot;Grande hache&quot;&gt;grande hache&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riel-Descalade-(Objet).html&quot; title=&quot;Mat&#233;riel d&amp;#39;escalade&quot;&gt;mat&#233;riel d&#39;escalade&lt;/a&gt;, 250 po
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;Il existe peu de choses aussi terrifiantes qu’un barbare demi-orque maniant une grande hache.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Barru la Sanglante&lt;a class=&quot;headeranchor&quot; id=&quot;Barru_la_Sanglante_0&quot; href=&quot;#Barru_la_Sanglante_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Barru la Sanglante l&#232;che le sang qui d&#233;gouline de sa hache &#224; chaque fois qu’elle terrasse un ennemi.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Rencontres hostiles.&lt;/b&gt; Barru la Sanglante s’allie avec tous ceux qui lui promettent de nombreux carnages.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Suggestions d’interpr&#233;tation.&lt;/b&gt; Il est tr&#232;s difficile de s’entendre avec Barru la Sanglante car elle pr&#233;f&#232;re tuer les gens plut&#244;t que de discuter avec eux.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
